import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.yo2CxoV2.js";const u=JSON.parse('{"title":"表单与调查问卷","description":"","frontmatter":{},"headers":[],"relativePath":"guides/surveys.md","filePath":"guides/surveys.md","lastUpdated":1794344792000}'),o={name:"guides/surveys.md"};function i(c,t,l,s,n,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="表单与调查问卷" tabindex="-1">表单与调查问卷 <a class="header-anchor" href="#表单与调查问卷" aria-label="Permalink to &quot;表单与调查问卷&quot;">​</a></h1><p>在大屏或 H5 中拖入表单组件，配置题目后选择站内收集或外部 POST 地址。编辑预览用于试填，站内实际提交发生在已保存的公开页面。</p><h2 id="题目与校验" tabindex="-1">题目与校验 <a class="header-anchor" href="#题目与校验" aria-label="Permalink to &quot;题目与校验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>内容</th></tr></thead><tbody><tr><td><code>text</code></td><td>单行文本</td></tr><tr><td><code>textarea</code></td><td>多行文本</td></tr><tr><td><code>email</code></td><td>邮箱</td></tr><tr><td><code>tel</code></td><td>电话</td></tr><tr><td><code>number</code></td><td>数字</td></tr><tr><td><code>radio</code></td><td>单选</td></tr><tr><td><code>checkbox</code></td><td>多选</td></tr><tr><td><code>select</code></td><td>下拉选择</td></tr><tr><td><code>rating</code></td><td>评分</td></tr><tr><td><code>date</code></td><td>日期</td></tr><tr><td><code>time</code></td><td>时间</td></tr><tr><td><code>datetime</code></td><td>本地日期时间</td></tr></tbody></table><p>支持 1–40 题，题目标识唯一且稳定，标签最多 200 字符。选择题使用 1–30 个非空且不重复的选项。 可以增删、排序题目并设置必填；服务端再次验证题目类型、格式、长度和答案范围。 日期、时间和本地日期时间不隐式换算时区，按题目语义保存。</p><h2 id="条件与跳题" tabindex="-1">条件与跳题 <a class="header-anchor" href="#条件与跳题" aria-label="Permalink to &quot;条件与跳题&quot;">​</a></h2><p>每题支持 1–5 条全部/任一显示条件，只引用前题；单选/下拉可跳至后题或结束。隐藏题不校验必填，浏览器清除原答案，服务端丢弃隐藏值。历史快照保留规则，详情、统计和导出只计入实际显示题目。配置步骤和例子见 <a href="./conditional-pages-and-antv-reports.html">条件问卷指南</a>。</p><h2 id="开放收集" tabindex="-1">开放收集 <a class="header-anchor" href="#开放收集" aria-label="Permalink to &quot;开放收集&quot;">​</a></h2><ol><li>在组件中选择站内收集，开启「开放收集」。</li><li>保存页面，核对分享开关、有效期、密码及链接令牌。</li><li>通过公开链接试填并提交，检查回执。</li><li>在资源管理入口查看收集结果。</li></ol><p>提交保留 Django CSRF、分享状态和访问凭据检查，并有请求去重和提交频控。 关闭/过期分享或停止收集会阻止新提交；密码失败还受 <a href="./sharing-and-task-diagnostics.html">共享限速</a> 控制。 外部地址模式按题目稳定标识进行原生 POST，由目标服务负责处理。</p><h2 id="答卷、导出与汇总" tabindex="-1">答卷、导出与汇总 <a class="header-anchor" href="#答卷、导出与汇总" aria-label="Permalink to &quot;答卷、导出与汇总&quot;">​</a></h2><p>当前资源管理者可以按表单、时间和关键词筛选答卷，查看明细、CSV/Excel 导出与统计。 每份答卷保存当时的题目快照；改题不会改写已提交答案，汇总按题目版本分别统计。 选择题显示分布，评分和数字支持统计；数字使用精确 Decimal 规则，导出不把字符串公式当作可执行公式。</p><p>关键词与汇总受有界扫描预算限制，超过限额时缩小时间或表单范围。删除页面会连同该页答卷删除。 条件跳题尚未开发。源码已新增数据库投影检索与私有后台导出，尚未包含在已发布的 1.0.1 中；启用、迁移和权限边界见 <a href="./operations-and-submission-exports.html">答卷后台导出指南</a>。</p>',13)])])}const m=d(o,[["render",i]]);export{u as __pageData,m as default};
